import hashlib,json,os,subprocess,time
from collections import Counter
from datetime import UTC,datetime
from email import policy
from email.parser import Parser
from pathlib import Path
from django.utils.crypto import constant_time_compare
started=time.perf_counter()
metadata=json.loads(subprocess.check_output(['docker','inspect','web-modelos-app-1'],text=True))[0]
for entry in metadata['Config']['Env']:
 key,_,value=entry.partition('=')
 if key in {'DJANGO_SECRET_KEY','SAFETY_ENCRYPTION_KEY'}:os.environ[key]=value
os.environ.setdefault('DJANGO_SETTINGS_MODULE','config.settings')
import django
django.setup()
from apps.safety.retained_log_origins import checked_capture
from scripts.collect_access_resource_logs import subject_log_signature
from scripts.inventory_retained_origins import inspect_origin
from scripts.scope_retained_redis_origin import read_origin
expected={'schema','subject_kind','subject_id','operation','outcome','created_at','signature'}
operations={'media_processing_started','media_processing_completed','media_processing_failed','profile_viewed','profile_updated','contact_verified','rights_record_read','rights_response_issued'}
headers={'content-type','mime-version','content-transfer-encoding','subject','from','to','date','message-id'}
sources=[]
for evidence in ['logs-historicos-inventario0110.json','logs-historicos-nueva-captura0110.json']:
 sources.extend(json.loads((Path('docs/evidencias')/evidence).read_text())['origins'])
results=[];total=Counter();total_bytes=Counter();mime_stats=Counter()
for source in sources:
 before=inspect_origin(source['path'])
 if before['sha256']!=source['sha256']:raise ValueError('Changed ciphertext')
 body=read_origin(source['path']);checked_capture(body,datetime.now(UTC));streams=[]
 for record in body['records']:
  for stream in ['stdout','stderr']:
   lines=record[stream].splitlines(keepends=True);classes=[];raws=[]
   for line in lines:
    category='unstructured_or_unrecognized';raw=None;timestamp=None
    try:
     timestamp,raw=line.rstrip('\r\n').split(' ',1);timestamp=datetime.fromisoformat(timestamp)
     if timestamp.tzinfo is None:raise ValueError('Naive line timestamp')
     if timestamp>datetime.fromisoformat(body['captured_at']):
      category='line_after_capture_pending'
     elif not raw:
      category='empty_payload'
     else:
      try:event=json.loads(raw)
      except (ValueError,TypeError):event=None
      if isinstance(event,dict):
       category='json_object_without_subject_protocol'
       if event.get('schema')=='subject-operation-v1':
        category='subject_protocol_invalid_or_unverifiable'
        try:
         event_time=datetime.fromisoformat(event['created_at'])
         if (set(event)==expected and all(isinstance(event[k],str) for k in expected)
             and event['subject_kind'] in {'account','person','photo_blob'} and event['subject_id']
             and event['operation'] in operations and event['outcome'] in {'succeeded','failed','denied','pending'}
             and event_time.tzinfo is not None and event_time<=timestamp
             and constant_time_compare(event['signature'],subject_log_signature(event))):
          category='signed_subject_protocol_association_unreviewed'
        except (ValueError,TypeError,KeyError):pass
    except (ValueError,TypeError):category='timestamp_unrecognized_pending'
    classes.append(category);raws.append(raw)
   block=[];size=0
   for index,raw in enumerate(raws):
    if raw is None:
     if block:mime_stats['interrupted_blocks']+=1
     block=[];size=0;continue
    if raw.startswith('Content-Type:'):
     if block:mime_stats['superseded_blocks']+=1
     block=[];size=0
    if raw=='-'*79 and block:
     message=Parser(policy=policy.default).parsestr('\n'.join(raws[i] for i in block))
     names=[name.lower() for name in message.keys()]
     valid=(not message.defects and not message.is_multipart() and set(names)==headers and len(names)==len(headers)
            and message.get_content_type()=='text/plain' and message.get_content_charset()=='utf-8'
            and not any(getattr(value,'defects',()) for value in message.values()))
     category='complete_console_mime_association_unreviewed' if valid else 'console_mime_unsupported_pending'
     for i in block+[index]:classes[i]=category
     mime_stats['complete_supported_blocks' if valid else 'closed_unsupported_blocks']+=1
     block=[];size=0
    elif block or raw.startswith('Content-Type:'):
     size+=len(raw.encode())
     if size<=262144:block.append(index)
     else:
      mime_stats['oversized_blocks']+=1
      for i in block+[index]:classes[i]='console_mime_oversized_pending'
      block=[];size=0
   if block:
    mime_stats['unterminated_blocks']+=1
    for i in block:classes[i]='console_mime_unterminated_pending'
   counts=Counter(classes);byte_counts=Counter()
   for line,category in zip(lines,classes,strict=True):byte_counts[category]+=len(line.encode())
   if sum(byte_counts.values())!=len(record[stream].encode()):raise ValueError('Byte accounting mismatch')
   total.update(counts);total_bytes.update(byte_counts)
   streams.append({'service':record['service'],'stream':stream,'lines':len(lines),'bytes':sum(byte_counts.values()),'classes':dict(counts),'class_bytes':dict(byte_counts)})
 if inspect_origin(source['path'])!=before:raise ValueError('Source changed during classification')
 results.append({'ciphertext_sha256':source['sha256'],'captured_at':body['captured_at'],'streams':streams})
result={'schema':'historical-log-structure-diagnosis-v1','source_commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'observed_at':datetime.now(UTC).isoformat(),'sources':len(results),'origins':results,'classes':dict(total),'class_bytes':dict(total_bytes),'console_mime':dict(mime_stats),'lines':sum(total.values()),'stream_bytes':sum(total_bytes.values()),'observed_seconds':time.perf_counter()-started,'sources_preserved':True,'plaintext_files_written':False,'subject_association_verified':False,'partial':True,'phase_accepted':False,'method_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'pending':['structured_format_does_not_accredit_subject_or_disclosure','unstructured_or_unknown_content_association_and_accounting','other_host_mail_cache_backup_sources','retention_authority_and_independent_custody'],'reproduction':{'command':['env','PYTHONPATH=.','.venv/bin/python',str(Path(__file__))],'method_source':Path(__file__).read_text()}}
Path('docs/evidencias/logs-historicos-formatos0110.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:result[k] for k in ['sources','classes','console_mime','lines','stream_bytes','observed_seconds','partial']}))
